import socket
import ipaddress
import requests
from urllib.parse import urlparse
from requests.adapters import HTTPAdapter
from urllib3.util.retry import Retry

def get_ip_geolocation(host: str, timeout: float = 5.0, token: str = None, retries: int = 2):
    """
    Resolve the given host to an IP address and fetch geolocation data for that IP from ipinfo.io.

    Parameters:
    - host: A hostname, an IP address, or a URL (the hostname part will be used).
    - timeout: Timeout (in seconds) for network operations (DNS lookup and HTTP request).
    - token: Optional ipinfo.io token. If provided, it will be appended as ?token=<token>.
    - retries: Number of retry attempts for the HTTP request on transient errors.

    Returns:
    A dict with either:
      {'success': True, 'ip': '<resolved-ip>', 'geo': { ... ipinfo JSON ... }}
    or
      {'success': False, 'error': '<human-friendly error message>'}

    Notes:
    - Uses Python stdlib for DNS resolution and 'requests' (open-source) for HTTP.
    - Handles invalid hostnames, network errors, private/reserved IPs, HTTP errors, and JSON errors.
    """

    # Normalize host: if a URL is provided, extract the hostname
    if not host:
        return {'success': False, 'error': 'No host provided.'}
    parsed = urlparse(host if '://' in host else '//' + host)  # ensures netloc parsed correctly
    hostname = parsed.hostname or host

    # First check if the provided hostname is already an IP address literal
    try:
        ip_obj = ipaddress.ip_address(hostname)
        resolved_ip = str(ip_obj)
    except ValueError:
        # Not a literal IP — resolve via DNS
        try:
            # getaddrinfo may return multiple addresses; prefer IPv4 (AF_INET) then IPv6
            infos = socket.getaddrinfo(hostname, None)
            ipv4 = None
            ipv6 = None
            for fam, _, _, _, sockaddr in infos:
                if fam == socket.AF_INET and not ipv4:
                    ipv4 = sockaddr[0]
                elif fam == socket.AF_INET6 and not ipv6:
                    # sockaddr for IPv6 is (addr, port, flowinfo, scopeid)
                    ipv6 = sockaddr[0]
            resolved_ip = ipv4 or ipv6
            if not resolved_ip:
                return {'success': False, 'error': f'Could not resolve an IP address for host: {hostname}'}
        except socket.gaierror as e:
            return {'success': False, 'error': f'DNS resolution failed for {hostname}: {e}'}
        except Exception as e:
            return {'success': False, 'error': f'Unexpected error during DNS resolution: {e}'}

    # Validate resolved IP and detect private / reserved addresses where geolocation is meaningless
    try:
        ip_obj = ipaddress.ip_address(resolved_ip)
        if ip_obj.is_private or ip_obj.is_loopback or ip_obj.is_reserved or ip_obj.is_unspecified or ip_obj.is_multicast:
            return {
                'success': False,
                'error': f'Resolved IP {resolved_ip} is private/reserved/loopback/multicast — geolocation is not available.'
            }
    except ValueError:
        return {'success': False, 'error': f'Resolved value is not a valid IP address: {resolved_ip}'}

    # Prepare requests session with retries for transient HTTP errors
    session = requests.Session()
    retry = Retry(
        total=retries,
        backoff_factor=0.3,
        status_forcelist=(429, 500, 502, 503, 504),
        allowed_methods=frozenset(['GET', 'HEAD', 'OPTIONS'])
    )
    adapter = HTTPAdapter(max_retries=retry)
    session.mount('https://', adapter)
    session.mount('http://', adapter)

    # Build ipinfo.io URL. If token supplied, pass as query param.
    url = f'https://ipinfo.io/{resolved_ip}/json'
    params = {}
    if token:
        params['token'] = token

    try:
        resp = session.get(url, params=params, timeout=timeout)
    except requests.exceptions.Timeout:
        return {'success': False, 'error': 'Timeout while contacting ipinfo.io.'}
    except requests.exceptions.ConnectionError as e:
        return {'success': False, 'error': f'Network connection error while contacting ipinfo.io: {e}'}
    except Exception as e:
        return {'success': False, 'error': f'Unexpected error while contacting ipinfo.io: {e}'}

    # Check HTTP response status
    if resp.status_code == 401:
        return {'success': False, 'error': 'Unauthorized access to ipinfo.io. Check your token.'}
    if resp.status_code == 429:
        return {'success': False, 'error': 'Rate limited by ipinfo.io (HTTP 429). Try again later.'}
    if resp.status_code != 200:
        return {'success': False, 'error': f'ipinfo.io returned HTTP {resp.status_code}.'}

    # Parse JSON body
    try:
        geo = resp.json()
    except ValueError:
        return {'success': False, 'error': 'Received invalid JSON from ipinfo.io.'}

    # ipinfo returns {"error": {"title": "...", "message": "..."}} in some cases
    if isinstance(geo, dict) and 'error' in geo:
        err = geo.get('error')
        msg = err.get('message') if isinstance(err, dict) else str(err)
        return {'success': False, 'error': f'ipinfo.io error: {msg}'}

    # If ipinfo indicates bogon (reserved) IP, treat as unavailable
    if isinstance(geo, dict) and geo.get('bogon'):
        return {'success': False, 'error': f'IP {resolved_ip} is bogon/reserved according to ipinfo.io.'}

    return {'success': True, 'ip': resolved_ip, 'geo': geo}
