import random
from typing import Dict, Any, List, Tuple
import pandas as pd

def veg_statistics(people_to_veg: Dict[Any, Any], seed: int = None) -> Dict[str, Dict]:
    """
    Given a dictionary mapping people -> vegetable or people -> list/tuple/set of vegetables,
    reverse the mapping to vegetables -> people, assign random counts (1-10) to each vegetable,
    compute each vegetable's percentage share of the total counts, and create a mapping
    from each vegetable to a single person (randomly chosen among those who prefer it).

    Parameters:
    - people_to_veg: dict where keys are people identifiers and values are either:
        - a single vegetable as a string, or
        - an iterable (list/tuple/set) of vegetables.
    - seed: optional int to seed the random number generator for reproducible results.

    Returns: dict with keys:
    - "veg_to_people": Dict[vegetable, List[people]]
    - "veg_counts": Dict[vegetable, int]           # random counts between 1 and 10
    - "veg_percentages": Dict[vegetable, float]    # percentage of total counts (rounded 2 decimals)
    - "veg_to_person_sample": Dict[vegetable, person]  # one person per vegetable (random choice if multiple)

    Example:
    >>> people = {"Alice": "carrot", "Bob": ["lettuce","carrot"], "Cory": "tomato"}
    >>> veg_statistics(people, seed=1)
    {
      "veg_to_people": {"carrot": ["Alice","Bob"], "lettuce": ["Bob"], "tomato": ["Cory"]},
      "veg_counts": {"carrot": 3, "lettuce": 10, "tomato": 2},
      "veg_percentages": {"carrot": 18.75, "lettuce": 62.5, "tomato": 12.5},
      "veg_to_person_sample": {"carrot": "Bob", "lettuce": "Bob", "tomato": "Cory"}
    }
    """
    if seed is not None:
        random.seed(seed)

    # Build reverse mapping: vegetable -> list of people
    veg_to_people: Dict[Any, List[Any]] = {}
    for person, vegs in people_to_veg.items():
        # normalize to iterable of vegetables
        if isinstance(vegs, (list, tuple, set)):
            items = list(vegs)
        else:
            items = [vegs]
        for veg in items:
            veg_to_people.setdefault(veg, []).append(person)

    # If no vegetables, return empty structures
    if not veg_to_people:
        return {
            "veg_to_people": {},
            "veg_counts": {},
            "veg_percentages": {},
            "veg_to_person_sample": {}
        }

    # Assign random counts (1-10) to each vegetable
    veg_counts = {veg: random.randint(1, 10) for veg in veg_to_people.keys()}

    # Calculate percentages using pandas for convenience
    s = pd.Series(veg_counts)
    total = s.sum()
    if total == 0:
        # avoid division by zero, but counts are 1-10 so shouldn't happen
        veg_percentages = {veg: 0.0 for veg in veg_counts}
    else:
        veg_percentages = s.div(total).mul(100).round(2).to_dict()

    # Map each vegetable to one person from the list (randomly pick if multiple)
    veg_to_person_sample = {
        veg: (random.choice(people) if isinstance(people, list) and len(people) > 1 else people[0])
        for veg, people in veg_to_people.items()
    }

    return {
        "veg_to_people": veg_to_people,
        "veg_counts": veg_counts,
        "veg_percentages": veg_percentages,
        "veg_to_person_sample": veg_to_person_sample
    }
