import re
import requests
from urllib.parse import urlparse

def fetch_api_response(input_text: str, timeout: int = 10):
    """
    Extract the first HTTP/HTTPS URL from input_text, send a GET request, and return the response parsed as JSON.

    Returns:
      - On success: the parsed JSON (usually a dict or list).
      - On failure: a dict with an 'error' key and additional info.

    Example:
      fetch_api_response("Please call https://api.example.com/data for info")
    """
    if not isinstance(input_text, str) or not input_text.strip():
        return {"error": "Input must be a non-empty string"}

    # Find first http(s) URL (simple heuristic)
    match = re.search(r"(https?://[^\s'\"<>]+)", input_text)
    if not match:
        return {"error": "No URL found in input"}

    url = match.group(1).rstrip(".,;:")  # remove trailing punctuation commonly attached to URLs

    # Basic validation
    parsed = urlparse(url)
    if not parsed.scheme or not parsed.netloc:
        return {"error": "Extracted URL is invalid", "url": url}

    try:
        headers = {"Accept": "application/json, text/json, application/*+json"}
        resp = requests.get(url, timeout=timeout, headers=headers)
        resp.raise_for_status()
    except requests.RequestException as e:
        return {"error": "Request failed", "message": str(e)}

    # Try to parse JSON
    try:
        return resp.json()
    except ValueError:
        # Response not JSON; return helpful info
        return {
            "error": "Response is not valid JSON",
            "status_code": resp.status_code,
            "text": resp.text[:1000]  # include up to first 1000 chars of body
        }
```

