from typing import Any, List, Dict, Union
import numpy as np
from collections import Counter

def analyze_degrees(items: List[Any]) -> Dict[str, Any]:
    """
    Sorts the input list in ascending order based on the 'degree' value of its elements,
    then computes mean, median and mode of:
      - the sorted degree values
      - the magnitudes of the FFT of those degree values (rounded to the nearest integer)

    The function accepts:
      - a list of numeric values (ints/floats), or
      - a list of dicts containing a 'degree' key, or
      - a list of objects with a .degree attribute

    Returns a dictionary with:
      - 'sorted_items': the input items sorted by degree (original items preserved)
      - 'degrees': list of degree values (floats) in sorted order
      - 'degree_stats': dict with 'mean', 'median', 'mode' (mode is a list; empty if no repeated value)
      - 'fft_magnitudes_rounded': list of FFT magnitude values rounded to nearest integer (ints)
      - 'fft_stats': dict with 'mean', 'median', 'mode' (mode is a list; empty if no repeated value)

    Example:
      items = [{'degree': 3}, {'degree': 1}, {'degree': 2}]
      out = analyze_degrees(items)
    """
    def _extract_degree(x: Any) -> float:
        # Try to extract degree as number from various possible element shapes
        # Order: dict-like ['degree'], attribute .degree, numeric directly
        try:
            # dict-like (mapping)
            if isinstance(x, dict) and 'degree' in x:
                return float(x['degree'])
        except Exception:
            pass
        try:
            # attribute access
            if hasattr(x, 'degree'):
                return float(getattr(x, 'degree'))
        except Exception:
            pass
        # numeric-like
        if isinstance(x, (int, float, np.integer, np.floating)):
            return float(x)
        # try item access fallback
        try:
            val = x['degree']  # if supports __getitem__
            return float(val)
        except Exception:
            pass
        raise ValueError(f"Could not extract a numeric 'degree' from item: {x!r}")

    if not isinstance(items, list):
        raise TypeError("Input must be a list of items (numbers, dicts with 'degree', or objects with .degree).")

    # Build (item, degree) pairs, extracting degrees and sorting items by degree
    pairs = []
    for it in items:
        deg = _extract_degree(it)
        pairs.append((it, deg))
    # Sort by degree value
    pairs_sorted = sorted(pairs, key=lambda p: p[1])
    sorted_items = [p[0] for p in pairs_sorted]
    degrees = [float(p[1]) for p in pairs_sorted]

    # Basic stats functions
    def _mean(xs: List[float]) -> float:
        return float(np.mean(xs)) if len(xs) > 0 else float('nan')

    def _median(xs: List[float]) -> float:
        return float(np.median(xs)) if len(xs) > 0 else float('nan')

    def _modes(xs: List[Union[float,int]], round_decimals: int = 8) -> List[Union[float,int]]:
        # To handle floating point equality safely, round values to round_decimals for counting
        if len(xs) == 0:
            return []
        rounded = [round(float(x), round_decimals) for x in xs]
        cnt = Counter(rounded)
        most_common = cnt.most_common()
        if not most_common:
            return []
        max_count = most_common[0][1]
        if max_count == 1:
            # no repeated value -> return empty list to indicate "no mode"
            return []
        modes_rounded = [val for val, c in most_common if c == max_count]
        # Return original-typed modes if possible: convert to int when they are whole numbers
        modes_out = []
        for v in modes_rounded:
            if float(v).is_integer():
                modes_out.append(int(v))
            else:
                modes_out.append(float(v))
        return modes_out

    degree_stats = {
        'mean': _mean(degrees),
        'median': _median(degrees),
        'mode': _modes(degrees)
    }

    # FFT of degree values (use numpy.fft.fft), take magnitude and round to nearest integer
    if len(degrees) == 0:
        fft_mags_rounded = []
    else:
        deg_array = np.array(degrees, dtype=float)
        fft_vals = np.fft.fft(deg_array)
        fft_mags = np.abs(fft_vals)
        # Round to nearest integer
        fft_mags_rounded_arr = np.rint(fft_mags).astype(np.int64)
        fft_mags_rounded = [int(x) for x in fft_mags_rounded_arr]

    fft_stats = {
        'mean': _mean(fft_mags_rounded) if len(fft_mags_rounded) > 0 else float('nan'),
        'median': _median(fft_mags_rounded) if len(fft_mags_rounded) > 0 else float('nan'),
        'mode': _modes(fft_mags_rounded, round_decimals=0)  # integer values; rounding decimal irrelevant
    }

    return {
        'sorted_items': sorted_items,
        'degrees': degrees,
        'degree_stats': degree_stats,
        'fft_magnitudes_rounded': fft_mags_rounded,
        'fft_stats': fft_stats
    }
```

Notes:
- This function uses numpy (open source) for numeric calculations and FFT.
- Mode is returned as a list of most frequent values; if there is no repeated value (all unique) the list is empty.
- The FFT magnitudes are rounded to the nearest integer before computing FFT statistics.

