import os
import re
from sklearn.feature_extraction.text import ENGLISH_STOP_WORDS

def count_unique_non_stop_words(dir_path, recursive=False):
    """
    Count unique non-stop words across all '.txt' files in dir_path.

    Parameters:
    - dir_path (str): Path to the directory containing .txt files.
    - recursive (bool): If True, search subdirectories recursively. Default False.

    Returns:
    - int: Number of unique non-stop words found.

    Notes:
    - Uses scikit-learn's ENGLISH_STOP_WORDS (install with: pip install scikit-learn).
    - Words are lowercased, alphabetic parts and apostrophes are accepted; internal apostrophes are removed
      (e.g., "don't" -> "dont"). Numbers and non-letter tokens are ignored.
    """
    if not os.path.isdir(dir_path):
        raise ValueError(f"Not a directory: {dir_path}")

    stop_words = set(ENGLISH_STOP_WORDS)
    token_re = re.compile(r"[A-Za-z']+")

    unique_words = set()

    def process_file(path):
        try:
            with open(path, 'r', encoding='utf-8', errors='ignore') as fh:
                text = fh.read()
        except OSError:
            return
        for raw in token_re.findall(text):
            # normalize: lowercase, strip surrounding apostrophes, remove internal apostrophes
            token = raw.lower().strip("'").replace("'", "")
            if token and token not in stop_words:
                unique_words.add(token)

    if recursive:
        for root, _, files in os.walk(dir_path):
            for fname in files:
                if fname.lower().endswith('.txt'):
                    process_file(os.path.join(root, fname))
    else:
        for fname in os.listdir(dir_path):
            path = os.path.join(dir_path, fname)
            if os.path.isfile(path) and fname.lower().endswith('.txt'):
                process_file(path)

    return len(unique_words)
