```
import os
import shutil
from typing import List
from openpyxl import load_workbook
from openpyxl.utils.exceptions import InvalidFileException

def protect_double_quotes_in_directory(directory: str, recursive: bool = False, backup: bool = True) -> List[str]:
    """
    Protects every double quote (") in all .xlsx files in `directory` by prefixing it with
    a double backslash (so each " becomes \\").
    - Processes only cell values that are Python strings (not numeric/datetime/etc).
    - Skips cells whose string value looks like a formula (starts with '='), to avoid breaking formulas.
    - By default creates a backup copy of each file as "<filename>.xlsx.bak" before overwriting.

    Parameters:
        directory: path to the folder containing .xlsx files.
        recursive: if True, search subdirectories recursively.
        backup: if True, create a .bak copy of each workbook before saving changes.

    Returns:
        list of file paths that were modified.
    """
    modified_files = []

    if not os.path.isdir(directory):
        raise ValueError(f"Directory not found: {directory}")

    def iter_xlsx_files(root_dir):
        if recursive:
            for root, _, files in os.walk(root_dir):
                for fname in files:
                    if fname.lower().endswith('.xlsx'):
                        yield os.path.join(root, fname)
        else:
            for fname in os.listdir(root_dir):
                if fname.lower().endswith('.xlsx'):
                    yield os.path.join(root_dir, fname)

    # Replacement string: two backslashes followed by a double quote (\\")
    replacement = '\\\\\"'  # Python literal for: backslash, backslash, double-quote

    for filepath in iter_xlsx_files(directory):
        try:
            wb = load_workbook(filepath)
        except (InvalidFileException, Exception) as e:
            print(f"Skipping '{filepath}': could not open workbook ({e})")
            continue

        changed = False
        for ws in wb.worksheets:
            # iterate over cells (cell objects so we can assign)
            for row in ws.iter_rows(values_only=False):
                for cell in row:
                    val = cell.value
                    if isinstance(val, str) and '"' in val:
                        # skip formulas that start with '=' to avoid breaking them
                        if val.startswith('='):
                            continue
