def random_string_similarity(s, letters, min_length, max_length):
    """
    Generate a random string (length between min_length and max_length, inclusive)
    using characters from `letters`, and compute its similarity to `s`.

    Uses rapidfuzz (if installed) for Levenshtein normalized similarity (0.0-1.0),
    otherwise falls back to difflib.SequenceMatcher.ratio().

    Returns a tuple: (random_string, similarity_score, is_similar)
      - random_string: the generated string
      - similarity_score: float in [0.0, 1.0]
      - is_similar: True if similarity_score >= 0.5 else False

    Raises ValueError for invalid inputs.

    Example:
      rand, score, similar = random_string_similarity("hello", "abcdefghijklmnopqrstuvwxyz", 3, 8)
    """
    import random

    # choose similarity function (rapidfuzz if available, otherwise difflib)
    try:
        from rapidfuzz.distance import Levenshtein
        def _similar(a, b):
            return float(Levenshtein.normalized_similarity(a, b))
    except Exception:
        import difflib
        def _similar(a, b):
            return float(difflib.SequenceMatcher(None, a, b).ratio())

    # input validation
    if not isinstance(s, str):
        raise ValueError("s must be a string")
    if not letters:
        raise ValueError("letters must be a non-empty sequence of characters")
    if not isinstance(min_length, int) or not isinstance(max_length, int):
        raise ValueError("min_length and max_length must be integers")
    if min_length < 0 or max_length < 0:
        raise ValueError("min_length and max_length must be non-negative")
    if min_length > max_length:
        raise ValueError("min_length must be <= max_length")

    length = random.randint(min_length, max_length)
    rand_str = ''.join(random.choices(letters, k=length))
    score = _similar(s, rand_str)
    is_similar = score >= 0.5
    return rand_str, score, is_similar

