    Plot a bar chart of monthly data values for a single year (months on x-axis, values on y-axis).

    Parameters
    - data: one of
        * dict: keys are month numbers (1-12) or month names/abbreviations (e.g. 'Jan', 'January', 'jan')
                values are numeric.
        * list/tuple/ndarray of length 12: values in order Jan..Dec.
        * pandas.Series (optional): index can be month numbers, names, or a DatetimeIndex.
    - year: optional int or str used only to help form the title.
    - ax: optional matplotlib Axes to plot into. If None, a new figure/axes are created.
    - figsize: tuple for new figure size (used only if ax is None).
    - title: optional chart title. If None and year is given, title becomes "Monthly values — <year>".
    - month_format: 'short' for Jan, Feb... or 'long' for January, February...
    - color: bar color.
    - show: if True (default), calls plt.show() before returning.
    - grid: if True, show horizontal grid lines.

    Returns
    - fig, ax: matplotlib Figure and Axes objects.

    Example usage:
    plot_monthly_bar([10, 12, 8, 9, 11, 13, 7, 6, 5, 8, 9, 10], year=2023)
    plot_monthly_bar({'Jan': 10, 'Feb': 12, 3: 8, 'April': 9})
    """
    import matplotlib.pyplot as plt
    import numpy as np
    import calendar

    # Optional pandas handling if available
    try:
        import pandas as _pd
    except Exception:
        _pd = None

    # Helper: parse month label (int or str) to month index 1..12
    def _month_to_int(m):
        if m is None:
            raise ValueError("Month label is None")
        if isinstance(m, (int, np.integer)):
            if 1 <= int(m) <= 12:
                return int(m)
            raise ValueError(f"Invalid month integer: {m}")
        s = str(m).strip().lower().rstrip('.')
        if s.isdigit():
            val = int(s)
            if 1 <= val <= 12:
                return val
        # match full names and abbreviations
        for i in range(1, 13):
            if s == calendar.month_name[i].lower() or s == calendar.month_abbr[i].lower():
                return i
        # try matching first three letters
        for i in range(1, 13):
            if s == calendar.month_name[i][:3].lower() or s == calendar.month_abbr[i][:3].lower():
                return i
        raise ValueError(f"Unrecognized month label: {m}")

    # Build mapping month_index -> value
    values = np.full(12, np.nan, dtype=float)
    # Case: list/tuple/ndarray of length 12
    if isinstance(data, (list, tuple, np.ndarray)):
        arr = np.asarray(data)
        if arr.ndim != 1 or arr.size != 12:
            raise ValueError("If data is a list/tuple/ndarray it must contain 12 values (Jan..Dec).")
        values[:] = arr.astype(float)
    # Case: pandas Series (optional)
    elif _pd is not None and isinstance(data, _pd.Series):
        ser = data
        if isinstance(ser.index, _pd.DatetimeIndex):
            # aggregate by month if multiple years present: sum-last?? Here assume single-year or use mean
            # We'll take values grouped by month in index order (if multiple years, user should pass single-year series)
            months = ser.index.month
            for m, v in zip(months, ser.values):
                values[m - 1] = float(v)
        else:
            for key, v in zip(ser.index, ser.values):
                m = _month_to_int(key)
                values[m - 1] = float(v)
    # Case: dict-like
    elif isinstance(data, dict):
        for k, v in data.items():
            m = _month_to_int(k)
            values[m - 1] = float(v)
    else:
        # Attempt duck typing for array-like with .index and .values (other libraries)
        if hasattr(data, 'index') and hasattr(data, 'values'):
            idx = data.index
            vals = data.values
            if hasattr(idx, 'month'):  # maybe DatetimeIndex-like
                months = [getattr(i, 'month', None) for i in idx]
                for m, v in zip(months, vals):
                    if m is None:
                        raise ValueError("Could not extract month from index entries.")
                    values[int(m) - 1] = float(v)
            else:
                for k, v in zip(idx, vals):
                    m = _month_to_int(k)
                    values[m - 1] = float(v)
        else:
            raise ValueError("Unsupported data type. Provide dict, list/tuple of 12 values, or pandas.Series.")

    # Prepare labels
    if month_format == 'long':
        labels = [calendar.month_name[i] for i in range(1, 13)]
    else:
        labels = [calendar.month_abbr[i] for i in range(1, 13)]

    x = np.arange(12)
    masked = np.ma.masked_invalid(values)  # bars not drawn for NaN

    # Create axes if needed
    if ax is None:
        fig, ax = plt.subplots(figsize=figsize)
    else:
        fig = ax.figure

    bars = ax.bar(x, masked, color=color, edgecolor='black', linewidth=0.5)

    ax.set_xticks(x)
    ax.set_xticklabels(labels, rotation=45, ha='right')
    ax.set_xlabel('Month')
    ax.set_ylabel('Value')
    if title is None:
        if year is not None:
            ax.set_title(f"Monthly values — {year}")
    else:
        ax.set_title(title)

    if grid:
        ax.yaxis.grid(True, linestyle='--', alpha=0.5)

    # Annotate missing months with a light hatch or label if any NaNs present
    if np.isnan(values).any():
        # light gray rectangle behind missing ticks to indicate missing
        for i, v in enumerate(values):
            if np.isnan(v):
                ax.bar(i, 0, color='lightgray', alpha=0.4)

    plt.tight_layout()
    if show:
        plt.show()
    return fig, ax
