Below is a self-contained Python function that uses the open-source requests library to fetch GitHub user information, recursively normalizes all string data (including dict keys and list items) to ASCII using Unicode NFKD normalization, and returns the normalized dictionary. It raises a RuntimeError on network/API errors.

Note: install requests if needed (pip install requests).

```python
import requests
import unicodedata
from typing import Any

def get_github_user_ascii(username: str, timeout: float = 10.0) -> dict:
    """
    Retrieve GitHub user information for the given username and normalize all string data to ASCII.

    Parameters:
    - username: GitHub username to look up.
    - timeout: request timeout in seconds (default 10.0).

    Returns:
    - A dictionary mirroring the JSON returned by the GitHub API, but with all strings converted to ASCII.

    Raises:
    - RuntimeError on network issues or non-200 responses from the GitHub API.
    """
    if not isinstance(username, str) or not username:
        raise ValueError("username must be a non-empty string")

    url = f"https://api.github.com/users/{username}"
    headers = {
        "Accept": "application/vnd.github.v3+json",
        "User-Agent": "python-requests"
    }

    try:
        resp = requests.get(url, headers=headers, timeout=timeout)
        resp.raise_for_status()
    except requests.HTTPError as e:
        # Include response body for debugging (may contain a JSON "message")
        text = resp.text if resp is not None else ""
        raise RuntimeError(f"GitHub API error {getattr(resp, 'status_code', 'unknown')}: {text}") from e
    except requests.RequestException as e:
        raise RuntimeError(f"Network error while contacting GitHub API: {e}") from e

    try:
        data = resp.json()
    except ValueError as e:
        raise RuntimeError("Received invalid JSON from GitHub API") from e

    def to_ascii(s: str) -> str:
        # Normalize to NFKD and drop non-ASCII characters
        return unicodedata.normalize("NFKD", s).encode("ascii", "ignore").decode("ascii")

    def normalize(obj: Any) -> Any:
        # Recursively normalize strings in dicts and lists
        if isinstance(obj, str):
            return to_ascii(obj)
        if isinstance(obj, dict):
            new = {}
            for k, v in obj.items():
                # Normalize keys if they are strings
                new_key = to_ascii(k) if isinstance(k, str) else k
                new[new_key] = normalize(v)
            return new
        if isinstance(obj, list):
            return [normalize(item) for item in obj]
        # numbers, booleans, None, etc. left unchanged
        return obj

    return normalize(data)

# Example usage:
