import requests
import unicodedata
from typing import Any, Dict

def get_github_user_normalized(username: str, timeout: int = 10) -> Dict[str, Any]:
    """
    Retrieve GitHub user information for `username`, normalize all string values to ASCII,
    and return a dictionary with the normalized data.

    - Uses the open-source `requests` library to call the GitHub REST API.
    - Normalizes Unicode strings to ASCII using Unicode NFKD normalization and
      removal of non-ASCII characters (accents, etc.).
    - Recursively normalizes strings in nested dicts, lists, and tuples.
    - Raises a ValueError if username is not found (404) or invalid input,
      and raises requests.HTTPError for other HTTP errors.

    Parameters:
    - username: GitHub username (str)
    - timeout: HTTP request timeout in seconds (default 10)

    Returns:
    - dict: JSON response from GitHub with all string values normalized to ASCII.

    Example:
    >>> get_github_user_normalized("torvalds")
    {'login': 'torvalds', 'id': 1024025, 'node_id': 'MDQ6VXNlcjEwMjQwMjU=', 'avatar_url': 'https://avatars.githubusercontent.com/u/1024025?v=4', ...}
    """
    if not isinstance(username, str) or not username:
        raise ValueError("username must be a non-empty string")

    def _normalize_strings(obj: Any) -> Any:
        """Recursively normalize all string values in obj to ASCII."""
        if isinstance(obj, str):
            # Normalize (decompose accents), then drop any remaining non-ASCII bytes
            normalized = unicodedata.normalize("NFKD", obj)
            return normalized.encode("ascii", "ignore").decode("ascii")
        if isinstance(obj, dict):
            # Keep keys as-is (they are usually ASCII in API responses), normalize values
            return {k: _normalize_strings(v) for k, v in obj.items()}
        if isinstance(obj, list):
            return [_normalize_strings(v) for v in obj]
        if isinstance(obj, tuple):
            return tuple(_normalize_strings(v) for v in obj)
        # Other types (int, bool, None, etc.) are returned unchanged
        return obj

    url = f"https://api.github.com/users/{username}"
    headers = {
        "Accept": "application/vnd.github.v3+json",
        "User-Agent": "github-user-normalizer/1.0"
    }

    resp = requests.get(url, headers=headers, timeout=timeout)

    if resp.status_code == 404:
        raise ValueError(f'GitHub user "{username}" not found (404).')
    # For other non-2xx responses, raise an HTTPError
    resp.raise_for_status()

    data = resp.json()  # may raise ValueError if response is not JSON
    return _normalize_strings(data)


