Here's a small self-contained Python function that uses the open-source collections.Counter to count occurrences of values for keys "x", "y", and "z" in a list of dictionaries. It also handles some common unhashable values (lists, dicts) by converting them to a hashable representation.

```python
def count_values_by_keys(dicts, keys=('x', 'y', 'z')):
    """
    Count occurrences of values for specified keys in a list of dictionaries.

    Args:
        dicts (iterable): Iterable of dictionaries to inspect.
        keys (iterable): Keys to count values for (default: ('x','y','z')).

    Returns:
        dict: Mapping key -> collections.Counter of value occurrences.
              Values that were unhashable (lists/dicts) are converted to
              a hashable representation (tuples or tuples of items).
    """
    from collections import Counter

    def make_hashable(v):
        """Return a hashable representation of v (convert lists/dicts)."""
        try:
            hash(v)
            return v
        except TypeError:
            # handle common unhashables
            if isinstance(v, list):
                return tuple(make_hashable(i) for i in v)
            if isinstance(v, dict):
                return tuple((k, make_hashable(v[k])) for k in sorted(v))
            return repr(v)

    counters = {k: Counter() for k in keys}
    for item in dicts:
        if not isinstance(item, dict):
            continue
        for k in keys:
            if k in item:
                counters[k][make_hashable(item[k])] += 1

    return counters

# Example usage:
if __name__ == "__main__":
    d = [
        {'x': 1, 'y': 'a'},
        {'x': 2, 'y': 'a', 'z': [1, 2]},
        {'x': 1, 'y': 'b', 'z': [1, 2]},
        {'y': 'a', 'z': {'p': 1}},
    ]
    result = count_values_by_keys(d)
    from pprint import pprint
    pprint(result)
    # Example output:
    # {'x': Counter({1: 2, 2: 1}),
    #  'y': Counter({'a': 3, 'b': 1}),
    #  'z': Counter({(1, 2): 2, (('p', 1),): 1})}
