Here's a self-contained Python function that extracts numeric values from a JSON-like structure following a specified path (supports dot-separated string or list of keys, and "*" wildcard to iterate over lists/dicts), and visualizes the extracted numbers using matplotlib. It returns the list of extracted values and the matplotlib Figure/Axis objects.

Usage examples are included in the docstring.

```python
import json
from typing import Any, List, Tuple, Union, Optional
import matplotlib.pyplot as plt

def extract_and_visualize_json_values(
    json_input: Union[str, dict, list],
    path: Union[str, List[Union[str, int]]],
    plot: str = "hist",
    bins: int = 30,
    figsize: Tuple[int, int] = (8, 4),
    title: Optional[str] = None,
    xlabel: Optional[str] = None,
    ylabel: Optional[str] = None,
    show: bool = True,
    parse_numeric_strings: bool = False,
    plot_kwargs: Optional[dict] = None
) -> Tuple[List[float], "plt.Figure", "plt.Axes"]:
    """
    Extract numeric values from a JSON structure following 'path' and visualize them.

    Parameters
    - json_input: JSON string or already-parsed Python object (dict/list).
    - path: Either a dot-separated string like "items.*.price" or a list of keys,
            where "*" is a wildcard that iterates all dict values or list items
            at that level. List indices may be used as integers (or numeric strings).
    - plot: One of "hist" (histogram), "line" (line plot by order), "box" (boxplot),
            "scatter" (index vs value scatter). Default "hist".
    - bins: Number of bins for histogram (if used).
    - figsize: Figure size tuple.
    - title, xlabel, ylabel: Optional labels for the plot.
    - show: If True, calls plt.show(). Set False if embedding in another UI.
    - parse_numeric_strings: If True, attempt to parse numeric-looking strings into floats.
    - plot_kwargs: Extra keyword args forwarded to the matplotlib plotting call.

    Returns:
    - values: list of extracted numeric values (floats).
    - fig, ax: matplotlib Figure and Axes objects for further customization.

    Examples:
    data = {
        "items": [
            {"price": 10.5, "name": "A"},
            {"price": 7, "name": "B"},
            {"price": "12.3", "name": "C"}
        ],
        "meta": {"count": 3}
    }
    # Extract all prices under items: use wildcard to iterate list items
    vals, fig, ax = extract_and_visualize_json_values(data, "items.*.price", parse_numeric_strings=True)

    # If JSON string:
    json_str = '{"users":[{"score": 5}, {"score": 8}]}'
    vals, fig, ax = extract_and_visualize_json_values(json_str, ["users", "*", "score"], plot="line")
    """
    # Parse json_input if it's a string
    if isinstance(json_input, str):
        try:
            obj = json.loads(json_input)
        except Exception as e:
            raise ValueError(f"json_input string could not be parsed as JSON: {e}")
    else:
        obj = json_input

    # Normalize path to list of keys
    if isinstance(path, str):
        parts: List[Union[str, int]] = path.split(".") if path != "" else []
    elif isinstance(path, list):
        parts = path.copy()
    else:
        raise TypeError("path must be a dot-separated string or a list of keys")

    # Helper to test numeric (exclude bool)
    def is_number(x: Any) -> bool:
        return (isinstance(x, (int, float)) and not isinstance(x, bool))

    def try_parse_number(x: Any) -> Optional[float]:
        if is_number(x):
            return float(x)
        if parse_numeric_strings and isinstance(x, str):
            try:
                return float(x)
            except ValueError:
                return None
        return None

    results: List[float] = []

    # Recursive traversal
    def traverse(current: Any, remaining_path: List[Union[str, int]]):
        if not remaining_path:
            # At the end of path: collect numbers (if current is list/dict, attempt to find numeric leaves)
            if is_number(current):
                results.append(float(current))
                return
            if parse_numeric_strings and isinstance(current, str):
                try:
                    results.append(float(current))
                    return
                except ValueError:
                    return
            # If current is list or dict, try to collect numeric leaves inside
            if isinstance(current, list):
                for item in current:
                    traverse(item, [])
            elif isinstance(current, dict):
                for v in current.values():
                    traverse(v, [])
            return

        key = remaining_path[0]
        rest = remaining_path[1:]

        # Wildcard: iterate over values for dict or elements for list
        if key == "*":
            if isinstance(current, dict):
                for v in current.values():
                    traverse(v, rest)
            elif isinstance(current, list):
                for v in current:
                    traverse(v, rest)
            else:
                return
            return

        # If current is dict, look up key
        if isinstance(current, dict):
            # allow integer-like keys stored as strings
            k = key
            if isinstance(k, int):
                k = str(k)
                # if integer key exactly present in dict (rare), prefer int-like
            if k in current:
                traverse(current[k], rest)
            else:
                # Also attempt integer conversion for numeric-string keys
                try:
                    ik = int(k)
                except Exception:
                    ik = None
                if ik is not None and ik in current:
                    traverse(current[ik], rest)
            return

        # If current is list and key is integer or integer-like, index into list
        if isinstance(current, list):
            idx = None
            if isinstance(key, int):
                idx = key
            else:
                # try to parse as int string
                try:
                    idx = int(key)
                except Exception:
                    idx = None
            if idx is not None:
                if -len(current) <= idx < len(current):
                    traverse(current[idx], rest)
            else:
                # If key is not an index, try to apply the key to each element (like implicit wildcard)
                for v in current:
                    traverse(v, remaining_path)
            return

        # Otherwise can't proceed
        return

    traverse(obj, parts)

    if not results:
        # No numeric values found; raise informative error
        raise ValueError(f"No numeric values found at path {path!r} in the provided JSON input.")

    # Prepare plotting
    fig, ax = plt.subplots(figsize=figsize)
    pk = plot_kwargs or {}

    if plot == "hist":
        ax.hist(results, bins=bins, **pk)
        ax.set_ylabel(ylabel or "Frequency")
        ax.set_xlabel(xlabel or (parts[-1] if parts else "value"))
    elif plot == "line":
        ax.plot(results, **pk)
        ax.set_xlabel(xlabel or "index")
        ax.set_ylabel(ylabel or "value")
    elif plot == "box":
        ax.boxplot(results, **pk)
        ax.set_ylabel(ylabel or (parts[-1] if parts else "value"))
    elif plot == "scatter":
        ax.scatter(range(len(results)), results, **pk)
        ax.set_xlabel(xlabel or "index")
        ax.set_ylabel(ylabel or "value")
    else:
        raise ValueError(f"Unsupported plot type: {plot!r}. Choose from 'hist','line','box','scatter'.")

    if title:
        ax.set_title(title)
    else:
        ax.set_title(f"Extracted {len(results)} values from path {path!r}")

    plt.tight_layout()

    if show:
        plt.show()

    return results, fig, ax
```

