Here's a single self-contained Python function that extracts numeric values from a nested JSON-like structure based on a specified key path and visualizes them using matplotlib and pandas. The path can be either a list of keys or a dot-separated string; use '*' to mean "iterate over all items at this level" (works for lists and dicts). The function returns a pandas Series of numeric values it plotted.

Code:

```python
from typing import Any, List, Union
import matplotlib.pyplot as plt
import pandas as pd

def extract_and_visualize(
    json_data: Any,
    path: Union[str, List[Union[str,int]]],
    chart: str = "line",
    bins: int = 30,
    color: str = "C0",
    alpha: float = 0.8,
    figsize: tuple = (10, 4),
    title: str = None,
    xlabel: str = None,
    ylabel: str = None,
    show: bool = True,
    return_series: bool = True
) -> pd.Series:
    """
    Extract numeric values from a nested JSON-like structure following `path` and visualize them.

    Parameters:
    - json_data: nested dict/list structure (parsed JSON).
    - path: dot-separated string like 'data.items.*.value' or a list ['data','items','*','value'].
            Use '*' to iterate over all items of a list or all values of a dict at that level.
            If a list node is encountered but the key is a non-integer, the function will attempt
            to apply the same key to each element of the list.
    - chart: one of 'line', 'bar', 'hist' (default 'line').
    - bins: (for histogram) number of bins.
    - color: matplotlib color.
    - alpha: plot alpha.
    - figsize: matplotlib figure size.
    - title, xlabel, ylabel: plot labels.
    - show: whether to call plt.show().
    - return_series: whether to return a pandas.Series of numeric values.

    Returns:
    - pandas.Series of numeric values (index 0..n-1). Raises ValueError if no numeric values found.
    """

    # normalize path
    if isinstance(path, str):
        keys = [p for p in path.split(".") if p != ""]
    else:
        keys = [str(p) for p in path]

    def is_number(x):
        return (isinstance(x, (int, float)) and not isinstance(x, bool))

    def collect(node: Any, remaining_keys: List[str]) -> List[Any]:
        if not remaining_keys:
            # collect numeric leaves reachable from this node
            if is_number(node):
                return [node]
            if isinstance(node, list):
                out = []
                for el in node:
                    out.extend(collect(el, []))
                return out
            if isinstance(node, dict):
                out = []
                for v in node.values():
                    out.extend(collect(v, []))
                return out
            return []
        # still keys to follow
        key = remaining_keys[0]
        rest = remaining_keys[1:]
        results: List[Any] = []

        if key == "*":
            # iterate over all entries of dict or list
            if isinstance(node, dict):
                for v in node.values():
                    results.extend(collect(v, rest))
            elif isinstance(node, list):
                for el in node:
                    results.extend(collect(el, rest))
            else:
                # nothing to expand
                pass
            return results

        # normal key (try dict key, list index or apply to each list element)
        if isinstance(node, dict):
            if key in node:
                results.extend(collect(node[key], rest))
        elif isinstance(node, list):
            # try numeric index
            try:
                idx = int(key)
                if 0 <= idx < len(node):
                    results.extend(collect(node[idx], rest))
            except Exception:
                # apply the key path to each element in the list
                for el in node:
                    results.extend(collect(el, remaining_keys))
        else:
            # cannot follow further
            pass

        return results

    raw_values = collect(json_data, keys)
    if not raw_values:
        raise ValueError(f"No values found at path {path!r}")

    # convert to pandas Series of numeric, coercing non-numeric to NaN and dropping them
    ser = pd.to_numeric(pd.Series(raw_values), errors="coerce").dropna().reset_index(drop=True)

    if ser.empty:
        raise ValueError(f"No numeric values found at path {path!r}")

    # plotting
    plt.figure(figsize=figsize)
    if chart == "line":
        plt.plot(ser.index, ser.values, marker="o", color=color, alpha=alpha)
    elif chart == "bar":
        plt.bar(ser.index, ser.values, color=color, alpha=alpha)
    elif chart == "hist":
        plt.hist(ser.values, bins=bins, color=color, alpha=alpha)
    else:
        raise ValueError("Unsupported chart type. Use 'line', 'bar', or 'hist'.")

    if title:
        plt.title(title)
    if xlabel:
        plt.xlabel(xlabel)
    else:
        plt.xlabel("index" if chart != "hist" else "value")
    if ylabel:
        plt.ylabel(ylabel)
    else:
        plt.ylabel("value" if chart == "hist" else "value")

    plt.tight_layout()
    if show:
        plt.show()

    return ser if return_series else None


# Example usage:
if __name__ == "__main__":
    example_json = {
        "data": {
            "items": [
                {"value": 10, "name": "a"},
                {"value": 15, "name": "b"},
                {"value": 7,  "name": "c"},
                {"value": 21, "name": "d"}
            ],
            "summary": {"max": 21, "min": 7}
        }
    }

    # Extract the 'value' field for all items and draw a line chart
    s = extract_and_visualize(example_json, "data.items.*.value", chart="line", title="Values per item")
    print("Extracted series:\n", s)
```

Notes:
- The function uses pandas (pd.to_numeric/Series) and matplotlib for plotting (both open-source).
- Use '*' in the path to iterate through all items at that level. For lists, you may also use numeric indices.
- The function is defensive: it coerces values to numeric and drops non-numeric values, and raises a ValueError if no numeric values are found.

Here's a single self-contained Python function that parses a JSON string to extract numeric data, Min-Max normalizes it, and produces a line plot using matplotlib (open-source). It supports several common JSON shapes (list of numbers, list of objects with a chosen key or automatic detection, or a dict of numeric values). It can save the plot to a file or show it interactively and returns the extracted and normalized data.

```python
def process_json_minmax_plot(json_str, value_key=None, output_file=None, title=None, figsize=(10, 5)):
    """
    Parse a JSON string, extract numerical data, Min-Max normalize it, and plot a line chart.

    Parameters:
    - json_str (str): JSON-formatted string containing the data.
    - value_key (str, optional): If the JSON is a list of objects, this indicates which key (dot-separated
      path allowed, e.g. "sensor.value") to extract from each object. If None and the JSON is a list of objects,
      the function will try to auto-detect the most common numeric key.
    - output_file (str, optional): If provided, the plot will be saved to this path (e.g., "plot.png").
      If None, the plot will be shown via plt.show().
    - title (str, optional): Title for the plot.
    - figsize (tuple): Matplotlib figure size.

    Returns:
    - dict with keys:
        - "x": list of x labels/indices used for plotting
        - "values": list of original numeric values (floats)
        - "normalized": list of Min-Max normalized values in [0, 1]

    Supported JSON input formats:
    - A list of numbers: [1, 2, 3.5, 4]
    - A list of objects: [{"t": "2020-01-01", "val": 1}, {"t": "2020-01-02", "val": 2}]
      Use value_key="val" (or let the function auto-detect a numeric key).
      value_key can be dot-separated to access nested fields, e.g. "a.b".
    - A dict mapping keys to numeric values: {"a": 1, "b": 2}

    Notes:
    - Non-numeric or missing entries are skipped with a warning (printed).
    - If all extracted values are identical, normalized values will be zeros.
    """
    import json
    import math
    import numpy as np
    import matplotlib.pyplot as plt
    from collections import Counter

    def is_number(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool) and not (isinstance(x, float) and (math.isnan(x) or math.isinf(x)))

    def get_by_path(obj, path):
        # path like "a.b.0.c"
        parts = path.split('.') if path else []
        cur = obj
        try:
            for p in parts:
                if isinstance(cur, list):
                    # try numeric index if possible
                    idx = int(p)
                    cur = cur[idx]
                elif isinstance(cur, dict):
                    cur = cur[p]
                else:
                    return None
            return cur
        except (KeyError, IndexError, ValueError, TypeError):
            return None

    # parse JSON
    try:
        data = json.loads(json_str)
    except Exception as e:
        raise ValueError(f"Invalid JSON: {e}")

    x_labels = []
    values = []

    # Case: list
    if isinstance(data, list):
        if all(is_number(x) for x in data):
            values = [float(x) for x in data]
            x_labels = list(range(len(values)))
        elif all(isinstance(x, dict) for x in data):
            # list of dicts
            # If value_key provided, extract using path
            if value_key:
                for i, item in enumerate(data):
                    v = get_by_path(item, value_key)
                    if is_number(v):
                        values.append(float(v))
                        x_labels.append(i)
                    else:
                        print(f"Skipping entry {i}: missing/non-numeric value for key '{value_key}'")
            else:
                # auto-detect the most common numeric key across items
                key_counts = Counter()
                for item in data:
                    for k, v in item.items():
                        if is_number(v):
                            key_counts[k] += 1
                if not key_counts:
                    raise ValueError("No numeric fields found in list of objects. Provide value_key to select a field.")
                best_key, _ = key_counts.most_common(1)[0]
                for i, item in enumerate(data):
                    v = item.get(best_key)
                    if is_number(v):
                        values.append(float(v))
                        x_labels.append(i)
                    else:
                        print(f"Skipping entry {i}: missing/non-numeric value for auto-detected key '{best_key}'")
                value_key = best_key  # note what we used
        else:
            # list of mixed types or nested lists: try to pull numeric items
            for i, item in enumerate(data):
                if is_number(item):
                    values.append(float(item))
                    x_labels.append(i)
                else:
                    # try one-level dict with numeric single value
                    if isinstance(item, dict):
                        numeric_entries = [v for v in item.values() if is_number(v)]
                        if len(numeric_entries) == 1:
                            values.append(float(numeric_entries[0]))
                            x_labels.append(i)
                        else:
                            print(f"Skipping entry {i}: cannot determine numeric value in {item}")
                    else:
                        print(f"Skipping entry {i}: non-numeric item")
    # Case: dict mapping
    elif isinstance(data, dict):
        # if all values numeric -> use them sorted by key for deterministic order
        if all(is_number(v) for v in data.values()):
            keys_sorted = sorted(data.keys())
            x_labels = keys_sorted
            values = [float(data[k]) for k in keys_sorted]
        else:
            # try values that are lists or numbers: if any value is a list of numbers and all lists same length
            # else try to extract numeric values from dict values
            numeric_items = []
            for k, v in data.items():
                if is_number(v):
                    numeric_items.append((k, float(v)))
            if numeric_items:
                keys_sorted = [k for k, _ in sorted(numeric_items, key=lambda kv: kv[0])]
                x_labels = keys_sorted
                values = [v for _, v in sorted(numeric_items, key=lambda kv: kv[0])]
            else:
                raise ValueError("Dictionary does not contain numeric values to extract.")
    else:
        raise ValueError("Unsupported JSON top-level structure. Provide a list or dict.")

    if len(values) == 0:
        raise ValueError("No numeric values extracted from JSON input.")

    arr = np.array(values, dtype=float)
    min_v = arr.min()
    max_v = arr.max()
    if max_v == min_v:
        normalized = np.zeros_like(arr)
    else:
        normalized = (arr - min_v) / (max_v - min_v)

    # Plotting
    plt.figure(figsize=figsize)
    if all(isinstance(x, (int, float)) for x in x_labels) and list(x_labels) == list(range(len(x_labels))):
        plt.plot(normalized, marker='o', linestyle='-')
        plt.xticks(range(len(x_labels)))
        plt.xlabel("Index")
    else:
        # categorical x labels (e.g., keys)
        plt.plot(range(len(normalized)), normalized, marker='o', linestyle='-')
        plt.xticks(range(len(x_labels)), [str(x) for x in x_labels], rotation=45, ha='right')
        plt.xlabel("Key")
    plt.ylabel("Normalized (Min-Max)")
    if title:
        plt.title(title)
    else:
        plt.title("Min-Max Normalized Line Plot" + (f" (field={value_key})" if value_key else ""))

    plt.tight_layout()

    if output_file:
        plt.savefig(output_file, dpi=150)
        plt.close()
        print(f"Plot saved to: {output_file}")
    else:
        plt.show()

    return {"x": x_labels, "values": values, "normalized": normalized.tolist()}
```

Example usage:
- For a JSON list of numbers: process_json_minmax_plot('[1,2,3,4]')
- For a list of objects: process_json_minmax_plot('[{"t": "a", "v": 10}, {"t": "b", "v": 20}]', value_key='v')
- To save: process_json_minmax_plot('[1,2,3]', output_file='plot.png')

