from PIL import Image, ExifTags
import unicodedata

# The OCR library and encoding detector
try:
    import pytesseract
except Exception:
    pytesseract = None

try:
    import chardet
except Exception:
    chardet = None


def extract_text_from_image(path, ocr_lang='eng', tesseract_cmd=None, fallback_to_comment=True):
    """
    Open an image file, extract text using OCR (Tesseract via pytesseract) and convert/normalize encoding.
    If OCR yields no usable text, optionally fallback to reading image comments / EXIF user comment.

    Returns:
      A unicode Python string (normalized to NFC). If no text is found returns an empty string.

    Requirements:
      - Pillow (PIL)
      - pytesseract (and the tesseract binary available on PATH or provided via tesseract_cmd)
      - chardet (optional but used to robustly detect encodings for image comments)

    Parameters:
      path (str): path to image file
      ocr_lang (str): language code(s) for tesseract, e.g. 'eng' or 'eng+spa'
      tesseract_cmd (str|None): full path to tesseract executable if it's not on PATH
      fallback_to_comment (bool): if True, try extracting image comments/EXIF if OCR fails

    Example:
      text = extract_text_from_image("photo.jpg", ocr_lang='eng')
    """
    def _normalize_text(s):
        if s is None:
            return ''
        if isinstance(s, bytes):
            s = _decode_bytes(s)
        # ensure str
        if not isinstance(s, str):
            try:
                s = str(s)
            except Exception:
                s = ''
        # strip BOM and nulls, normalize
        s = s.lstrip('\ufeff').replace('\x00', '')
        s = unicodedata.normalize('NFC', s).strip()
        return s

    def _decode_bytes(b):
        # Try utf-8 first, then chardet, then fallback to latin-1 replace
        if not isinstance(b, (bytes, bytearray)):
            b = bytes(b)
        try:
            return b.decode('utf-8')
        except Exception:
            pass

        # Handle EXIF UserComment pattern (8-byte prefix like b'ASCII\\0\\0\\0', 'UNICODE\\0')
        if len(b) >= 8:
            prefix = b[:8]
            if prefix.startswith(b'ASCII'):
                try:
                    return b[8:].decode('ascii', errors='replace')
                except Exception:
                    pass
            if prefix.startswith(b'UNICODE'):
                try:
                    # usually UTF-16 with BOM or without; try utf-16:
                    return b[8:].decode('utf-16', errors='replace')
                except Exception:
                    pass

        if chardet is not None:
            try:
                guess = chardet.detect(b)
                enc = guess.get('encoding')
                if enc:
                    return b.decode(enc, errors='replace')
            except Exception:
                pass

        # Last-resort: latin-1 which maps bytes 1:1, avoiding decode exceptions.
        try:
            return b.decode('latin-1', errors='replace')
        except Exception:
            # As ultimate fallback
            return b.decode('utf-8', errors='ignore')

    # Try to open image
    try:
        img = Image.open(path)
    except Exception as e:
        raise IOError(f"Unable to open image {path}: {e}")

    # Configure tesseract path if provided
    if tesseract_cmd and pytesseract is not None:
        try:
            pytesseract.pytesseract.tesseract_cmd = tesseract_cmd
        except Exception:
            # ignore; will fail later if actually needed
            pass

    # Attempt OCR if pytesseract is available
    ocr_text = ''
    if pytesseract is not None:
        try:
            # Use image directly; can pass config options if desired
            ocr_text = pytesseract.image_to_string(img, lang=ocr_lang) or ''
        except Exception:
            ocr_text = ''

    ocr_text = _normalize_text(ocr_text)
    if ocr_text:
        return ocr_text

    # OCR produced nothing: fallback to comments / EXIF if requested
    if not fallback_to_comment:
        return ''

    candidates = []

    # 1) PIL image info dictionary often contains comments (PNG tEXt, JPEG comment)
    try:
        info = img.info or {}
        # Common keys: 'comment', 'Comment', 'XML:com.adobe.xmp', 'description', etc.
        for k, v in info.items():
            if v:
                candidates.append(v)
    except Exception:
        pass

    # 2) EXIF tags (ImageDescription, UserComment, XPComment, XPTitle)
    try:
        exif = img.getexif()
        if exif:
            # Build map name->value
            for tag_id, value in exif.items():
                tag = ExifTags.TAGS.get(tag_id, tag_id)
                if value:
                    candidates.append(value)
    except Exception:
        pass

    # 3) Try any candidate, decode and return first non-empty normalized text
    for c in candidates:
        text = _normalize_text(c)
        if text:
            return text

    # Nothing found
    return ''
