```python
"""
OCR + encoding-conversion helper with metadata/comment fallback.

Dependencies (open-source):
 - Pillow (PIL)     : pip install Pillow
 - pytesseract      : pip install pytesseract
 - Tesseract-OCR engine (native binary) must be installed on the system:
   https://github.com/tesseract-ocr/tesseract

Function:
 - Opens an image file
 - Runs OCR on it
 - If OCR yields no useful text, falls back to reading image comments / EXIF user comment
 - Optionally returns the result as a Unicode string or as bytes encoded to a requested encoding

Returns:
 - (text, source) where `text` is either a str (if output_encoding is None) or bytes (if output_encoding is given),
   and `source` is one of: 'ocr', 'comment', 'exif', 'png_text', or 'none'

Usage examples:
   text, src = ocr_extract_convert("photo.jpg")                      # Unicode string from OCR or metadata
   data, src = ocr_extract_convert("photo.jpg", output_encoding="utf-8")  # bytes in UTF-8
"""

from typing import Optional, Tuple, Union
from PIL import Image, PngImagePlugin, JpegImagePlugin, TiffImagePlugin
import pytesseract

def _decode_exif_user_comment(b: bytes) -> str:
    """
    Decode EXIF UserComment per EXIF spec:
      - starts with an 8-byte encoding hint like b'ASCII\\0\\0\\0' or b'UNICODE\\0' or b'JIS\\0\\0\\0\\0\\0'
    Fallback: try UTF-8, then latin-1.
    """
    if not b:
        return ""
    try:
        # If bytes already plain ASCII/UTF-8 text, try decode directly
        s = b.decode('utf-8', errors='strict')
        return s
    except Exception:
        pass
    # Check for the 8-byte prefix
    if len(b) >= 8:
        prefix = b[:8]
        payload = b[8:]
        if prefix.startswith(b'ASCII'):
            try:
                return payload.decode('ascii', errors='replace')
            except Exception:
                pass
        if prefix.startswith(b'UNICODE') or prefix.startswith(b'UTF-16'):
            try:
                # Often UTF-16 with BOM
                return payload.decode('utf-16', errors='replace')
            except Exception:
                pass
        if prefix.startswith(b'JIS'):
            try:
                return payload.decode('shift_jis', errors='replace')
            except Exception:
                pass
    # Last-resort guesses
    for enc in ('utf-8', 'utf-16', 'latin-1', 'cp1252'):
        try:
            return b.decode(enc, errors='replace')
        except Exception:
            continue
    # As final fallback
    return b.decode('latin-1', errors='replace')


def ocr_extract_convert(
    image_path: str,
    lang: str = 'eng',
    output_encoding: Optional[str] = None,
    fallback_to_comment: bool = True,
    ocr_config: Optional[str] = None,
    tesseract_cmd: Optional[str] = None,
    errors: str = 'replace'
) -> Tuple[Union[str, bytes], str]:
    """
    Open an image, extract text with OCR (pytesseract). If OCR returns no meaningful text,
    optionally try to extract image comments / EXIF user comment / PNG text chunks as a fallback.
    Optionally return the result encoded to a target encoding.

    Parameters:
      - image_path: path to the image file
      - lang: tesseract language(s) (e.g. 'eng', 'eng+rus')
      - output_encoding: if None, returns a Python str (unicode). If set (e.g. 'utf-8', 'cp1251'),
                         returns bytes in that encoding.
      - fallback_to_comment: if True, when OCR yields empty or whitespace-only text,
                             check image metadata/comments
      - ocr_config: additional config string passed to pytesseract (e.g. '--psm 6')
      - tesseract_cmd: optional path to tesseract executable; if provided, sets pytesseract.pytesseract.tesseract_cmd
      - errors: how to handle encoding errors when encoding to output_encoding (default 'replace')

    Returns:
      - (text, source) where source is one of:
          'ocr'         : text came from OCR
          'comment'     : came from image comment (JPEG COM or PIL info)
          'exif'        : came from EXIF UserComment
          'png_text'    : came from PNG tEXt / iTXt chunks via PIL info
          'none'        : nothing found (text will be '')

    Notes:
      - Requires Tesseract engine installed (not just the Python wrapper).
    """
    if tesseract_cmd:
        pytesseract.pytesseract.tesseract_cmd = tesseract_cmd

    # Open image
    img = Image.open(image_path)

    # Run OCR
    try:
        ocr_kwargs = {}
        if ocr_config:
            ocr_kwargs['config'] = ocr_config
        text = pytesseract.image_to_string(img, lang=lang, **ocr_kwargs)
    except Exception as e:
        # If tesseract fails for any reason, treat as empty OCR result and continue to fallback
        text = ""
    # Normalize whitespace
    if isinstance(text, str):
        normalized = text.strip()
    else:
        # shouldn't happen, but make safe
        try:
            normalized = str(text).strip()
        except Exception:
            normalized = ""

    source = 'ocr' if normalized else 'none'

    # Fallback to metadata/comments if OCR yielded nothing useful
    if (not normalized) and fallback_to_comment:
        # Try JPEG comment in info (Pillow may place it under 'comment' as bytes)
        info = getattr(img, "info", {}) or {}
        # 1) Common JPEG comment
        comment_obj = info.get('comment')
        if comment_obj:
            # comment_obj may be bytes or list of bytes for some decoders
            try:
                if isinstance(comment_obj, (list, tuple)) and comment_obj:
                    b = comment_obj[0] if isinstance(comment_obj[0], (bytes, bytearray)) else str(comment_obj[0]).encode('latin-1', errors='replace')
                elif isinstance(comment_obj, (bytes, bytearray)):
                    b = bytes(comment_obj)
                else:
                    # probably str
                    txt = str(comment_obj)
                    normalized = txt.strip()
                    source = 'comment'
                    b = None
                if b is not None:
                    try:
                        normalized = b.decode('utf-8', errors='strict').strip()
                    except Exception:
                        # try a couple fallbacks
                        for enc in ('latin-1', 'cp1252', 'utf-16'):
                            try:
                                normalized = b.decode(enc, errors='replace').strip()
                                break
                            except Exception:
                                continue
                    source = 'comment'
            except Exception:
                pass

        # 2) EXIF UserComment (common in JPEG/TIFF)
        if not normalized:
            try:
                exif = None
                if hasattr(img, "getexif"):
                    exif = img.getexif()  # returns a dict-like Exif object
                elif hasattr(img, "_getexif"):
                    exif = img._getexif()
                if exif:
                    # EXIF tag 37510 is UserComment
                    raw = exif.get(37510) if isinstance(exif, dict) else None
                    if raw:
                        # raw might be bytes or already a str
                        if isinstance(raw, str):
                            normalized = raw.strip()
                        else:
                            # bytes -> decode considering EXIF prefix
                            normalized = _decode_exif_user_comment(bytes(raw)).strip()
                        source = 'exif'
            except Exception:
                pass

        # 3) PNG tEXt / iTXt stored in PIL info dict (keys vary)
        if not normalized:
            try:
                # PIL stores PNG text chunks in img.info as key-value pairs (keys are the text keys)
                png_texts = {}
                for k, v in info.items():
                    # filter out typical non-user keys
                    if isinstance(k, str) and k.lower() not in ('icc_profile', 'gamma', 'transparency', 'dpi', 'background'):
                        png_texts[k] = v
                # If any textual keys present, take the largest one (heuristic)
                if png_texts:
                    # join all text values
                    merged = []
                    for v in png_texts.values():
                        if isinstance(v, (bytes, bytearray)):
                            try:
                                merged.append(v.decode('utf-8', errors='replace'))
                            except Exception:
                                merged.append(bytes(v).decode('latin-1', errors='replace'))
                        else:
                            merged.append(str(v))
                    candidate = "\n".join(merged).strip()
                    if candidate:
                        normalized = candidate
                        source = 'png_text'
            except Exception:
                pass

    # Ensure we have a string
    if not normalized:
        normalized = ""

    # Output encoding handling
    if output_encoding:
        try:
            out_bytes = normalized.encode(output_encoding, errors=errors)
            return out_bytes, source
        except Exception:
            # If requested encoding fails for some reason, fallback to utf-8 with replacement
            return normalized.encode('utf-8', errors='replace'), source
    else:
        return normalized, source


