```python
from typing import Tuple, Optional
from PIL import Image, ExifTags
import pytesseract
import chardet

def extract_text_from_image(
    image_path: str,
    target_encoding: str = "utf-8",
    ocr_lang: str = "eng",
    ocr_config: str = "",
    return_bytes: bool = False
) -> Tuple[Optional[bytes], str]:
    """
    Open an image, extract text using Tesseract OCR (pytesseract). If OCR yields no useful
    text, fall back to image comment/metadata (JPEG comment, PNG text chunks, EXIF tags).
    Attempt to detect and convert encodings for any byte-based metadata using chardet.

    Args:
        image_path: Path to the image file.
        target_encoding: Encoding to use for returned bytes if return_bytes=True.
                         Ignored if return_bytes=False (function returns a Python str).
        ocr_lang: Language code(s) for tesseract (e.g. 'eng' or 'eng+fra').
        ocr_config: Extra config string passed to pytesseract.image_to_string.
        return_bytes: If True, return bytes encoded with target_encoding; otherwise return a Python str.

    Returns:
        A tuple (text_or_bytes, source) where source is 'ocr', 'metadata', or 'none'.
        - If return_bytes is False: text_or_bytes is a Python str (decoded Unicode).
        - If return_bytes is True: text_or_bytes is bytes encoded with target_encoding.
          If no text found, returns ("", "none") or (b"", "none") accordingly.

    Notes:
        - Requires Tesseract OCR binary installed and accessible in PATH for OCR to work.
        - Uses chardet for encoding detection of metadata bytes.
    """
    def decode_bytes(b: bytes, fallback_enc: str = "utf-8") -> str:
        if not isinstance(b, (bytes, bytearray)):
            # Already a str
            return str(b)
        if not b:
            return ""
        try:
            guess = chardet.detect(b)
            enc = guess.get("encoding")
            if enc:
                try:
                    return b.decode(enc, errors="replace")
                except Exception:
                    pass
            # fallback
            try:
                return b.decode(fallback_enc, errors="replace")
            except Exception:
                return b.decode(errors="replace")
        except Exception:
            return b.decode(errors="replace")

    # Open image
    try:
        img = Image.open(image_path)
    except Exception as e:
        raise IOError(f"Cannot open image {image_path}: {e}")

    # 1) Try OCR
    ocr_text = ""
    try:
        ocr_text = pytesseract.image_to_string(img, lang=ocr_lang, config=ocr_config)
    except pytesseract.TesseractNotFoundError:
        ocr_text = ""
    except Exception:
        # any other OCR failure -> treat as no text and proceed to metadata
        ocr_text = ""

    ocr_text = (ocr_text or "").strip()
    if ocr_text:
        # We have OCR output (unicode str). Return as requested type.
        if return_bytes:
            return (ocr_text.encode(target_encoding, errors="replace"), "ocr")
        else:
            return (ocr_text, "ocr")

    # 2) Fallback: inspect image metadata / comments
    candidates = []

    # Basic info dict (PNG text, JPEG comment in some PIL builds)
    try:
        info = img.info or {}
        # Many info values might be str or bytes
        for k, v in info.items():
            # skip internal markers
            if k in ("icc_profile",):
                continue
            # Collect non-empty
            if v:
                candidates.append((k, v))
    except Exception:
        pass

    # EXIF tags
    try:
        exif = img.getexif()
        if exif:
            for tag_id, value in exif.items():
                tag = ExifTags.TAGS.get(tag_id, tag_id)
                if value:
                    candidates.append((f"EXIF:{tag}", value))
    except Exception:
        pass

    # Some formats expose text mapping separately (Pillow keeps some in info already).
    # Process candidates: prefer str values first, then bytes that can be decoded.
    chosen_text = ""
    chosen_source = "none"

    # First try any str-like candidate with reasonable content
    for key, val in candidates:
        if isinstance(val, str):
            v = val.strip()
            if v:
                chosen_text = v
                chosen_source = f"metadata:{key}"
                break

    # If none found as str, try bytes/bytearray candidates
    if not chosen_text:
        for key, val in candidates:
            if isinstance(val, (bytes, bytearray)):
                decoded = decode_bytes(bytes(val))
                decoded = decoded.strip()
                if decoded:
                    chosen_text = decoded
                    chosen_source = f"metadata:{key}"
                    break

    # As a last attempt, some EXIF UserComment may be a bytes starting with charset signature (8 bytes)
    # If any EXIF fields exist, try decoding any leftover bytes more heuristically
    if not chosen_text:
        for key, val in candidates:
            try:
                if isinstance(val, (bytes, bytearray)):
                    b = bytes(val)
                    # If it has an 8-byte EXIF user comment preamble, strip it and try decode
                    if len(b) > 8:
                        pre = b[:8]
                        # Common preambles: b'ASCII\\x00\\x00\\x00', b'UNICODE\\x00'
                        if pre[:5] in (b'ASCII',) or pre[:7] in (b'UNICODE',):
                            remainder = b[8:]
                            decoded = decode_bytes(remainder)
                            decoded = decoded.strip()
                            if decoded:
                                chosen_text = decoded
                                chosen_source = f"metadata:{key}"
                                break
            except Exception:
                continue

    # Return results
    if not chosen_text:
        if return_bytes:
            return (b"", "none")
        else:
            return ("", "none")

    if return_bytes:
        return (chosen_text.encode(target_encoding, errors="replace"), chosen_source)
    else:
        return (chosen_text, chosen_source)
```

