import requests
from datetime import datetime
from typing import Optional, Dict, Any

def fetch_github_repo_info(
    api_url: str,
    auth_token: Optional[str] = None,
    issues_threshold: int = 100,
    timeout: float = 10.0
) -> Dict[str, Any]:
    """
    Fetch and return GitHub repository information from a GitHub API URL.

    Parameters:
    - api_url: str
        The GitHub API URL for the repository, e.g. "https://api.github.com/repos/owner/repo".
    - auth_token: Optional[str]
        A personal access token to authenticate the request (helps avoid low rate limits).
    - issues_threshold: int
        If the repository's open_issues_count exceeds this value, a warning is printed.
    - timeout: float
        Timeout in seconds for the HTTP request.

    Returns:
    - dict: Parsed JSON response from the GitHub API describing the repository.

    Raises:
    - FileNotFoundError: If the repository is not found (404).
    - RuntimeError: For rate limit issues, other HTTP errors, or network problems.
    """
    headers = {"Accept": "application/vnd.github.v3+json"}
    if auth_token:
        headers["Authorization"] = f"token {auth_token}"

    try:
        resp = requests.get(api_url, headers=headers, timeout=timeout)
    except requests.exceptions.RequestException as e:
        # Network-level error (DNS failure, refused connection, etc.)
        raise RuntimeError(f"Network error while requesting {api_url}: {e}")

    # Helper to safely extract JSON message (if available)
    def _error_message_from_resp(r: requests.Response) -> str:
        try:
            payload = r.json()
            if isinstance(payload, dict) and "message" in payload:
                return str(payload.get("message"))
        except ValueError:
            # not JSON
            pass
        return r.text or f"HTTP {r.status_code}"

    status = resp.status_code

    # Check for rate limiting via status and headers
    rate_remaining = None
    rate_reset = None
    try:
        if "X-RateLimit-Remaining" in resp.headers:
            rate_remaining = int(resp.headers.get("X-RateLimit-Remaining", "0"))
    except ValueError:
        rate_remaining = None
    try:
        if "X-RateLimit-Reset" in resp.headers:
            # epoch seconds
            rate_reset = int(resp.headers.get("X-RateLimit-Reset"))
    except (ValueError, TypeError):
        rate_reset = None

    # Specific handling for common HTTP statuses
    if status == 200:
        # successful; parse JSON
        try:
            data = resp.json()
        except ValueError:
            raise RuntimeError(f"Received non-JSON response from {api_url}")

        # Warn if rate limit is about to be exhausted
        if rate_remaining is not None and rate_remaining <= 5 and rate_remaining >= 0:
            reset_msg = ""
            if rate_reset:
                reset_time = datetime.utcfromtimestamp(rate_reset).isoformat() + "Z"
                reset_msg = f" Rate limit resets at {reset_time} UTC."
            print(f"Warning: Low GitHub API rate limit remaining ({rate_remaining}).{reset_msg}")

        # Check open issues count and warn if large
        open_issues = None
        if isinstance(data, dict):
            open_issues = data.get("open_issues_count")  # GitHub repo field
        if isinstance(open_issues, int) and open_issues > issues_threshold:
            print(f"Warning: Repository reports {open_issues} open issues (threshold: {issues_threshold}).")

        return data

    elif status == 404:
        raise FileNotFoundError(f"Repository not found (404): {api_url}")

    elif status == 401:
        msg = _error_message_from_resp(resp)
        raise RuntimeError(f"Unauthorized (401) when accessing {api_url}: {msg}")

    elif status == 403:
        # Could be rate limit or forbidden access
        msg = _error_message_from_resp(resp).lower()
        if "rate limit" in msg or (rate_remaining is not None and rate_remaining <= 0):
            reset_info = ""
            if rate_reset:
                reset_time = datetime.utcfromtimestamp(rate_reset).isoformat() + "Z"
                reset_info = f" Rate limit will reset at {reset_time} UTC."
            raise RuntimeError(f"GitHub API rate limit exceeded.{reset_info} Consider authenticating with a token.")
        else:
            raise RuntimeError(f"Access forbidden (403) when accessing {api_url}: {_error_message_from_resp(resp)}")

    else:
        # Other HTTP errors
        raise RuntimeError(f"HTTP {status} error when accessing {api_url}: {_error_message_from_resp(resp)}")

