Here is a single self-contained Python function that extracts the first URL from a string and returns the page title (using the open-source libraries requests and BeautifulSoup). It returns an explanatory error string if no URL is found or the fetch/title extraction fails.

Note: install required libraries with "pip install requests beautifulsoup4" if you don't already have them.

```python
def extract_url_title(text, timeout=10):
    """
    Extract the first URL from `text` and return the HTML page <title>.
    Returns:
      - title string on success
      - descriptive error string on failure (no URL, fetch error, non-HTML, or no title)
    Uses: requests, beautifulsoup4 (bs4)
    """
    import re
    try:
        import requests
        from bs4 import BeautifulSoup
    except Exception as e:
        return f"Missing required library: {e}. Install with `pip install requests beautifulsoup4`."

    # 1) Find a URL-like substring (http(s):// or www.); fall back to bare domain if present
    m = re.search(r'\b(?:https?://|www\.)[^\s<>]+\b', text, flags=re.IGNORECASE)
    if m:
        url = m.group(0)
        if url.lower().startswith('www.'):
            url = 'http://' + url  # add scheme for requests
    else:
        # crude fallback for bare domains like example.com/path
        m2 = re.search(r'\b([A-Za-z0-9][A-Za-z0-9\-\_]{0,61}\.[A-Za-z]{2,})(/[^\s<>]*)?\b', text)
        if not m2:
            return "No URL found in input."
        url = m2.group(0)
        if not url.lower().startswith(('http://', 'https://')):
            url = 'http://' + url

    # 2) Fetch the URL
    try:
        headers = {'User-Agent': 'Mozilla/5.0 (compatible; URL-Title-Extractor/1.0)'}
        resp = requests.get(url, headers=headers, timeout=timeout, allow_redirects=True)
        resp.raise_for_status()
    except requests.RequestException as e:
        return f"Failed to fetch URL '{url}': {e}"

    # 3) Ensure HTML content
    content_type = resp.headers.get('Content-Type', '')
    if 'html' not in content_type.lower():
        return f"URL did not return HTML content (Content-Type: {content_type})"

    # 4) Parse HTML and extract title (with fallbacks)
    try:
        soup = BeautifulSoup(resp.text, 'html.parser')
    except Exception as e:
        return f"Failed to parse HTML from '{url}': {e}"

    # Primary: <title>
    if soup.title and soup.title.string and soup.title.string.strip():
        return soup.title.string.strip()

    # Fallbacks: og:title, twitter:title, meta[name=title]
    for attr in (('property', 'og:title'), ('name', 'twitter:title'), ('name', 'title')):
        meta = soup.find('meta', attrs={attr[0]: attr[1]})
        if meta:
            content = meta.get('content') or meta.get('value')
            if content and content.strip():
                return content.strip()

    return f"No title found on the page at '{url}'."
