import re
from typing import Dict
from urllib.parse import urlparse
import requests
from bs4 import BeautifulSoup

def extract_url_and_get_title(text: str, timeout: int = 10) -> Dict:
    """
    Extract the first URL from the provided text and fetch the page title.

    Returns a dict:
      - On success: {'ok': True, 'title': <title string>, 'url': <final URL>}
      - On failure: {'ok': False, 'error': <error message>}

    Notes:
      - Requires the 'requests' and 'beautifulsoup4' packages.
        Install with: pip install requests beautifulsoup4
      - The function looks for URLs starting with http(s):// or www.
      - Adds 'http://' to URLs that start with 'www.' so they can be fetched.
    """
    if not text or not isinstance(text, str):
        return {'ok': False, 'error': 'Input must be a non-empty string.'}

    # Find a URL that starts with http(s):// or www.
    url_pattern = re.compile(r'(?i)\b((?:https?://|www\.)[^\s<>")\]\}]+)')
    m = url_pattern.search(text)
    if not m:
        return {'ok': False, 'error': 'No valid URL found in the input text.'}

    url = m.group(1).rstrip('.,;:!?)\]}\'')

    # If URL starts with www., prepend http://
    if url.lower().startswith('www.'):
        url = 'http://' + url

    # Validate URL scheme
    parsed = urlparse(url)
    if parsed.scheme not in ('http', 'https'):
        return {'ok': False, 'error': f'Unsupported URL scheme: {parsed.scheme!r}.'}

    headers = {
        'User-Agent': 'Mozilla/5.0 (compatible; TitleFetcher/1.0)'
    }

    try:
        resp = requests.get(url, headers=headers, timeout=timeout, allow_redirects=True)
    except requests.exceptions.RequestException as e:
        return {'ok': False, 'error': f'Failed to fetch the URL: {e}'}

    if not (200 <= resp.status_code < 300):
        return {'ok': False, 'error': f'HTTP request failed with status code {resp.status_code}.'}

    content_type = resp.headers.get('Content-Type', '')
    if 'text/html' not in content_type.lower():
        return {'ok': False, 'error': f'URL did not return HTML content (Content-Type: {content_type}).'}

    # Parse HTML and try to extract title
    try:
        soup = BeautifulSoup(resp.text, 'html.parser')
    except Exception as e:
        return {'ok': False, 'error': f'Failed to parse HTML: {e}'}

    title = None
    if soup.title and soup.title.string:
        title = soup.title.string.strip()

    # Fallbacks: common meta tags
    if not title:
        og = soup.find('meta', property='og:title')
        if og and og.get('content'):
            title = og['content'].strip()
    if not title:
        tw = soup.find('meta', attrs={'name': 'twitter:title'})
        if tw and tw.get('content'):
            title = tw['content'].strip()
    if not title:
        meta_title = soup.find('meta', attrs={'name': 'title'})
        if meta_title and meta_title.get('content'):
            title = meta_title['content'].strip()

    # Optional final fallback: first H1 text
    if not title:
        h1 = soup.find('h1')
        if h1 and h1.get_text(strip=True):
            title = h1.get_text(strip=True)

    if not title:
        return {'ok': False, 'error': 'Could not find a title in the HTML page.'}

    final_url = resp.url  # after redirects
    return {'ok': True, 'title': title, 'url': final_url}

